sources.BufferSession.ets:
export class BufferSession {
  private text: string = ''
  onMount(): void {
    this.reload()
  }
  async reload(): Promise<void> {
    this.text = await cache.load()
  }
  async commit(): Promise<void> {
    await cache.save(this.text)
  }
}

sources.WriteQueue.ets:
export class WriteQueue {
  async commit(text: string): Promise<void> {
    await cache.save(text)
  }
}

sources.TextPanel.ets:
export class TextPanel {
  private text: string = ''
  setText(next: string): void {
    this.text = next
  }
}

sources.SplitRoles.ets:
export class MountHandler {
  onMount(): void { notifyReady() }
}
export class CommitWriter {
  async commit(text: string): Promise<void> {
    await cache.save(text)
  }
}
export class StateHolder {
  private text: string = ''
  update(next: string): void { this.text = next }
}

sources.PendingQueue.ets:
export class PendingQueue {
  private tail: Promise<void> = Promise.resolve()
  append(text: string): void {
    this.tail = this.tail.then(async () => {
      await cache.save(text)
    })
  }
}

